//! Plan 008, T0: the position contract, generated by running upstream's
//! teleprompterPosition.ts over the same scripts.

use ontime_core::teleprompter::position::{map_offset_through_edit, reanchor, Anchor, Layout};
use ontime_core::teleprompter::script::ScriptEvent;
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SweepRow {
    row: f64,
    anchor: Option<Anchor>,
    back: Option<f64>,
    event_at: Option<String>,
}

#[derive(Deserialize)]
struct Sweep {
    name: String,
    events: Vec<ScriptEvent>,
    layout: Layout,
    rows: Vec<SweepRow>,
}

#[derive(Deserialize)]
struct AnchorCase {
    name: String,
    events: Vec<ScriptEvent>,
    anchor: Anchor,
    row: Option<f64>,
}

#[derive(Deserialize)]
struct Edit {
    name: String,
    previous: String,
    next: String,
    offset: usize,
    result: usize,
}

#[derive(Deserialize)]
struct Reanchor {
    name: String,
    previous: Vec<ScriptEvent>,
    next: Vec<ScriptEvent>,
    anchor: Option<Anchor>,
    result: Option<Anchor>,
}

#[derive(Deserialize)]
struct Cases {
    sweeps: Vec<Sweep>,
    anchors: Vec<AnchorCase>,
    edits: Vec<Edit>,
    reanchors: Vec<Reanchor>,
}

#[derive(Deserialize)]
struct Fixture {
    cases: Cases,
}

fn fixture() -> Cases {
    serde_json::from_str::<Fixture>(include_str!("fixtures/teleprompter_position.json")).unwrap().cases
}

#[test]
fn layouts_match_upstream() {
    for sweep in fixture().sweeps {
        assert_eq!(Layout::new(&sweep.events), sweep.layout, "{}", sweep.name);
    }
}

#[test]
fn rows_and_anchors_match_upstream_at_every_quarter_row() {
    let mut checked = 0;
    for sweep in fixture().sweeps {
        let layout = Layout::new(&sweep.events);
        for row in &sweep.rows {
            let anchor = layout.anchor_at(row.row);
            let label = format!("{} at row {}", sweep.name, row.row);
            assert_eq!(anchor, row.anchor, "anchor: {label}");
            assert_eq!(anchor.as_ref().and_then(|a| layout.row_of(a)), row.back, "back: {label}");
            assert_eq!(layout.event_at(row.row).map(|e| e.id.clone()), row.event_at, "event: {label}");
            checked += 1;
        }
    }
    assert!(checked > 100, "{checked}");
}

#[test]
fn anchors_resolve_like_upstream() {
    for case in fixture().anchors {
        assert_eq!(Layout::new(&case.events).row_of(&case.anchor), case.row, "{}", case.name);
    }
}

#[test]
fn offsets_move_through_edits_like_upstream() {
    for case in fixture().edits {
        let previous: Vec<u16> = case.previous.encode_utf16().collect();
        let next: Vec<u16> = case.next.encode_utf16().collect();
        assert_eq!(map_offset_through_edit(&previous, &next, case.offset), case.result, "{}", case.name);
    }
}

#[test]
fn readers_follow_edits_like_upstream() {
    for case in fixture().reanchors {
        assert_eq!(reanchor(&case.previous, &case.next, case.anchor.as_ref()), case.result, "{}", case.name);
    }
}
